﻿import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS,T,en,DUR,Easing,interpolate,clamp,FONT,Destello} from './kit';
// DINERO 29-nov 15:00 · ¿Cuánto quieres pagar al mes? (la cuota baja, los intereses suben). 2.5D: volumen (Vol), 3 capas con parallax, giro leve, sombra en el suelo.
export const SUBS={arriba:860,size:80,acento:'#FFC83D'};
const L='#FFC83D',NAVY='#0B1E4A',RJ='#FF4D4D';
const A=[0,8,28,48,60,85,107,119,138].map(T);
const P=(w:string,n=1)=>en(w,n)-.2; // la imagen entra 0,2 s antes de la palabra
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const qo=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.out(Easing.cubic)});
const ql=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],clamp);
const pop=(s:number,t:number)=>s<t?0:Math.max(0,1-Math.exp(-(s-t)*9)*Math.cos((s-t)*18));
const rnd=(i:number)=>{const x=Math.sin(i*127.1+311.7)*43758.5453;return x-Math.floor(x);};
const RAD=Math.PI/180;
type C3=[string,string,string];
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
// Cápsula cerrada de (x1,y1) a (x2,y2) con grosor w: dedos y brazos con volumen (nunca trazos sueltos).
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
const star=(n:number,r1:number,r2:number)=>Array.from({length:n*2}).map((_,j)=>{const a=j*Math.PI/n,r=j%2?r2:r1;return `${j?'L':'M'}${Math.cos(a)*r} ${Math.sin(a)*r}`;}).join('')+'Z';
const fmt=(n:number)=>Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g,'.');
const talk=(s:number,a:number,b:number)=>s>=a&&s<b?(.2+.6*Math.abs(Math.sin(s*14+Math.sin(s*5)*2))):0;
const PIEL_A:C3=['#f6cfae','#d09468','#80482a'],PIEL_T:C3=['#ffeadb','#f6c4a2','#b8764f'];
const PELO_A:C3=['#8a6650','#3d2417','#150a05'],PELO_T:C3=['#7a7a92','#16161e','#050508'];
const AZUL:C3=['#8fa4ff','#2448FF','#0a1a8a'],GRIS:C3=['#f0f3f8','#a0a9b8','#4c5466'],CORB:C3=['#ff9a9a','#FF3B3B','#8a0a14'];
const BLANCO:C3=['#ffffff','#f4f7fb','#aab4c6'],ORO:C3=['#fff3b0','#FFC83D','#a86a00'],COCHE:C3=['#ff7a8a','#E0122C','#5a0010'],MON:C3=['#ffb0b0','#FF4D4D','#8a0a14'];
const VERDE:C3=['#b8ffd0','#2ed47a','#0a6a38'],CRO:C3=['#ffffff','#b8c2d0','#4a5468'],ROSA:C3=['#ff9aa8','#d9546a','#8a2036'],LABIO_T:C3=['#e89a8a','#c4605a','#7a2a28'];
// Volumen: color medio, sombra suave abajo-derecha, luz suave arriba-izquierda y borde fino.
const Vol:React.FC<{id:string;d:string;c:C3;sw?:number;o?:number;borde?:string}>=({id,d,c,sw=70,o=24,borde})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;
// Volumen barato (sin desenfoque) para dedos, uñas y piezas chicas.
const VolS:React.FC<{id:string;d:string;c:C3;o?:number}>=({id,d,c,o=3})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={o*2.6} opacity={.8} transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={o*1.8} opacity={.85} transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={c[2]} strokeWidth={2} opacity={.5}/>
</g>;
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const Defs:React.FC=()=><defs>
 <filter id='b6' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='6'/></filter>
 <filter id='b18' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='18'/></filter>
 <filter id='b40' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='40'/></filter>
 <radialGradient id='luz'><stop stopColor='#ffffff' stopOpacity='.5'/><stop offset='1' stopColor='#ffffff' stopOpacity='0'/></radialGradient>
 <linearGradient id='diente' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#ffffff'/><stop offset='1' stopColor='#dcd6c8'/></linearGradient>
 <radialGradient id='hueco' cx='.5' cy='.4'><stop stopColor='#5a0a1e'/><stop offset='1' stopColor='#1c0008'/></radialGradient>
 <linearGradient id='vidrio' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#8fd0ff'/><stop offset='.5' stopColor='#244a80'/><stop offset='1' stopColor='#0a1830'/></linearGradient>
 <linearGradient id='cromo' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#ffffff'/><stop offset='.45' stopColor='#b8c2d0'/><stop offset='.55' stopColor='#6a7488'/><stop offset='1' stopColor='#dfe6f0'/></linearGradient>
 <linearGradient id='pared' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#1a3f9a'/><stop offset='1' stopColor='#0B1E4A'/></linearGradient>
 <linearGradient id='suelo' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#3a66d8'/><stop offset='.25' stopColor='#17388a'/><stop offset='1' stopColor='#061238'/></linearGradient>
 <linearGradient id='cielo' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#c8ecff'/><stop offset='1' stopColor='#5a9cf0'/></linearGradient>
 <linearGradient id='madera' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#d89a58'/><stop offset='.5' stopColor='#a8662c'/><stop offset='1' stopColor='#5a2c0e'/></linearGradient>
 <linearGradient id='tiraV' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#fff' stopOpacity='.55'/><stop offset='.45' stopColor='#fff' stopOpacity='0'/><stop offset='1' stopColor='#000' stopOpacity='.35'/></linearGradient>
 <linearGradient id='ladoM' x1='0' y1='0' x2='1' y2='0'><stop stopColor='#8a0a14'/><stop offset='.35' stopColor='#ff6a6a'/><stop offset='1' stopColor='#6a0010'/></linearGradient>
 <linearGradient id='ladoO' x1='0' y1='0' x2='1' y2='0'><stop stopColor='#a86a00'/><stop offset='.35' stopColor='#ffe27a'/><stop offset='1' stopColor='#8a5200'/></linearGradient>
 <linearGradient id='cielo2' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#2a1260'/><stop offset='.55' stopColor='#c8469a'/><stop offset='1' stopColor='#ffb36b'/></linearGradient>
 <linearGradient id='calle' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#2a3050'/><stop offset='1' stopColor='#0c1024'/></linearGradient>
 </defs>;
const Txt:React.FC<{x:number;y:number;t:string;size?:number;fill?:string;stroke?:string;sw?:number;anchor?:'start'|'middle'|'end';rot?:number;op?:number;sc?:number;sombra?:boolean}>=({x,y,t,size=80,fill='#fff',stroke=NAVY,sw=12,anchor='middle',rot=0,op=1,sc=1,sombra=true})=>
 <g opacity={op} transform={`translate(${x} ${y}) rotate(${rot}) scale(${sc})`}>
  {sombra&&<text x={5} y={9} textAnchor={anchor} fontFamily={FONT} fontWeight={900} fontSize={size} fill='#000' opacity={.35} stroke='#000' strokeWidth={sw} strokeLinejoin='round'>{t}</text>}
  <text textAnchor={anchor} fontFamily={FONT} fontWeight={900} fontSize={size} fill={fill} stroke={sw?stroke:'none'} strokeWidth={sw} strokeLinejoin='round' paintOrder='stroke'>{t}</text>
 </g>;
// ---------- PERSONAS (busto con volumen: orejas, nariz con fosas, ojos con iris y párpado, labios, cuello y ropa) ----------
const Persona:React.FC<{id:string;who:'ana'|'tomas';x:number;y:number;k?:number;rot?:number;s:number;sm?:number;open?:number;blink?:number;gx?:number;gy?:number;worry?:number;rise?:number;sweat?:number;gulp?:number;chispa?:number}>=({id,who,x,y,k=1,rot=0,s,sm=.3,open=0,blink=0,gx=0,gy=0,worry=0,rise=0,sweat=0,gulp=0,chispa=0})=>{
 const a=who==='ana',skin=a?PIEL_A:PIEL_T,hair=a?PELO_A:PELO_T,lab=a?ROSA:LABIO_T;
 const bob=Math.sin(s*1.6+(a?0:1.7))*5;
 const bl=Math.max(blink,Math.max(0,Math.sin(s*2.3+(a?0:2))-.965)*26);
 const cy=148-sm*28,uy=134,lc=cy+8+open*56+Math.max(0,sm)*34;
 const apU=.5*cy+.5*(uy+6),ap=.5*cy+.5*lc;
 const inner=`M-60 ${cy}Q0 ${uy+6} 60 ${cy}Q0 ${lc} -60 ${cy}Z`;
 const bi=-48-worry*14-rise*12,bo=-46+worry*8-rise*12;
 return <g transform={`translate(${x} ${y+bob}) rotate(${rot}) scale(${k})`}>
  {a&&<Vol id={id+'hb'} d='M-205 -30C-215 -230 -120 -300 0 -300C120 -300 215 -230 205 -30L240 440C150 490 -150 490 -240 440Z' c={PELO_A} sw={90} o={24}/>}
  <Vol id={id+'to'} d={a?'M-380 800C-370 500 -310 345 -150 300L0 340L150 300C310 345 370 500 380 800Z':'M-420 800C-410 500 -330 345 -150 300L0 340L150 300C330 345 410 500 420 800Z'} c={a?AZUL:GRIS} sw={130} o={36}/>
  {a?<>
   <path d='M-96 304Q0 392 96 304L0 560Z' fill='#fff'/><path d='M-96 304Q0 392 96 304' fill='none' stroke='#c8d0e0' strokeWidth={4}/>
   <Vol id={id+'l1'} d='M-150 300L-96 304L0 560L-70 640L-215 420Z' c={['#6a82ff','#1a38d8','#06126a']} sw={50} o={12}/>
   <Vol id={id+'l2'} d='M150 300L96 304L0 560L70 640L215 420Z' c={['#6a82ff','#1a38d8','#06126a']} sw={50} o={12}/>
  </>:<>
   <path d='M-94 296L0 430L94 296L56 272L-56 272Z' fill='#fff' stroke='#b8c0d0' strokeWidth={4}/>
   <Vol id={id+'l1'} d='M-150 300L-94 296L0 440L-80 600L-225 420Z' c={['#e0e6f0','#7a8496','#2c3446']} sw={50} o={12}/>
   <Vol id={id+'l2'} d='M150 300L94 296L0 440L80 600L225 420Z' c={['#e0e6f0','#7a8496','#2c3446']} sw={50} o={12}/>
   <Vol id={id+'kn'} d='M-32 322L32 322L26 376L-26 376Z' c={CORB} sw={20} o={6}/>
   <Vol id={id+'co'} d='M-28 376L28 376L42 570L0 620L-42 570Z' c={CORB} sw={30} o={8}/>
   <path d='M-8 392L-12 560M10 392L14 560' stroke='#fff' strokeWidth={4} opacity={.28}/>
  </>}
  <Vol id={id+'nk'} d='M-74 140L-82 340L82 340L74 140Z' c={skin} sw={50} o={14}/>
  <ellipse cy={190} rx={104} ry={44} fill={skin[2]} opacity={.45} filter='url(#b18)'/>
  {gulp>0&&<ellipse cx={0} cy={250+gulp*46} rx={20} ry={26} fill={skin[0]} opacity={.7} filter='url(#b6)'/>}
  {[-1,1].map(kk=><g key={kk}><Vol id={id+'e'+kk} d={ell(kk*182,12,30,52)} c={skin} sw={26} o={8}/><ellipse cx={kk*184} cy={14} rx={12} ry={26} fill={skin[2]} opacity={.35}/></g>)}
  <Vol id={id+'fc'} d={a?'M0 -228C118 -228 180 -140 178 -20C176 100 122 205 0 224C-122 205 -176 100 -178 -20C-180 -140 -118 -228 0 -228Z':'M0 -228C122 -228 184 -140 182 -20C180 112 128 214 0 228C-128 214 -180 112 -182 -20C-184 -140 -122 -228 0 -228Z'} c={skin} sw={140} o={40}/>
  {[-1,1].map(kk=><ellipse key={kk} cx={kk*98} cy={74} rx={50} ry={32} fill={a?'#ff7a6a':'#ff8a8a'} opacity={.28} filter='url(#b18)'/>)}
  {a?<>
   <Vol id={id+'h1'} d='M-190 80C-212 200 -224 330 -198 460L-132 450C-148 320 -140 200 -150 70Z' c={PELO_A} sw={50} o={14}/>
   <Vol id={id+'h2'} d='M190 80C212 200 224 330 198 460L132 450C148 320 140 200 150 70Z' c={PELO_A} sw={50} o={14}/>
   <Vol id={id+'hf'} d='M-190 -30C-214 -200 -110 -296 6 -292C140 -292 218 -196 192 -30C176 -108 142 -158 92 -176C46 -140 -50 -148 -100 -182C-150 -148 -176 -92 -190 -30Z' c={PELO_A} sw={60} o={16}/>
   <path d='M-120 -230Q-20 -280 100 -240' stroke='#fff' strokeWidth={10} fill='none' opacity={.22} strokeLinecap='round' filter='url(#b6)'/>
   {[-1,1].map(kk=><g key={kk}><circle cx={kk*186} cy={82} r={11} fill='#ffd34d' stroke='#a86a00' strokeWidth={3}/><circle cx={kk*183} cy={79} r={4} fill='#fff'/></g>)}
  </>:<>
   <Vol id={id+'hf'} d='M-184 -50C-198 -215 -100 -284 6 -284C134 -286 204 -204 186 -50C172 -112 130 -166 70 -184C20 -204 -60 -198 -120 -168C-158 -142 -176 -100 -184 -50Z' c={PELO_T} sw={60} o={16}/>
   <path d='M-110 -234Q0 -272 120 -226' stroke='#fff' strokeWidth={9} fill='none' opacity={.4} strokeLinecap='round' filter='url(#b6)'/>
   <path d='M-60 -196Q40 -230 130 -190' stroke='#fff' strokeWidth={4} fill='none' opacity={.3} strokeLinecap='round'/>
  </>}
  {[-1,1].map(kk=><g key={kk} transform={`translate(${kk*72} -22)`}>
   <defs><clipPath id={id+'ec'+kk}><path d='M-37 0Q0 -30 37 0Q0 26 -37 0Z'/></clipPath></defs>
   <g transform={`scale(1 ${Math.max(.1,1-bl)})`}>
    <path d='M-37 0Q0 -30 37 0Q0 26 -37 0Z' fill='#fff'/>
    <g clipPath={`url(#${id+'ec'+kk})`}><circle cx={gx} cy={gy} r={18} fill={a?'#6a3e1c':'#2f5f8f'}/><circle cx={gx} cy={gy} r={18} fill='none' stroke='#1a1008' strokeWidth={3} opacity={.5}/><circle cx={gx} cy={gy} r={8} fill='#0a0a0a'/><circle cx={gx+6} cy={gy-7} r={5} fill='#fff'/><circle cx={gx-6} cy={gy+6} r={2.5} fill='#fff' opacity={.7}/></g>
    <path d='M-39 2Q0 -32 39 2' stroke='#2a160c' strokeWidth={6} fill='none' strokeLinecap='round'/>
    {a&&<path d={`M${kk*36} -2L${kk*50} -10`} stroke='#2a160c' strokeWidth={5} strokeLinecap='round'/>}
   </g>
   <path d={`M${-kk*38} ${bi}Q0 ${(bi+bo)/2-16} ${kk*42} ${bo}`} stroke={hair[1]} strokeWidth={a?11:14} fill='none' strokeLinecap='round'/>
  </g>)}
  <path d='M-14 -20C-20 25 -48 55 -42 78C-30 98 -12 92 0 98C12 92 30 98 42 78C48 55 20 25 14 -20' fill={skin[1]} stroke={skin[2]} strokeWidth={3}/>
  <path d='M8 -10C12 30 28 55 30 72' stroke={skin[0]} strokeWidth={7} fill='none' opacity={.8} strokeLinecap='round'/>
  {[-1,1].map(kk=><ellipse key={kk} cx={kk*17} cy={87} rx={9} ry={5.5} fill='#5a2a1a'/>)}
  <defs><clipPath id={id+'mc'}><path d={inner}/></clipPath></defs>
  <path d={inner} fill='url(#hueco)'/>
  <g clipPath={`url(#${id+'mc'})`}>
   <rect x={-54} y={apU-4} width={108} height={36} rx={10} fill='url(#diente)'/>
   {[-36,-18,0,18,36].map(xx=><path key={xx} d={`M${xx} ${apU-2}V${apU+30}`} stroke='#c8c0b0' strokeWidth={1.5}/>)}
   {open>.25&&<rect x={-44} y={ap-22} width={88} height={30} rx={9} fill='url(#diente)'/>}
   {open>.2&&<ellipse cx={0} cy={ap+2} rx={34} ry={14} fill='#e8607a'/>}
  </g>
  <path d={`M-62 ${cy}Q-30 ${uy-16} 0 ${uy-8}Q30 ${uy-16} 62 ${cy}Q0 ${uy+6} -62 ${cy}Z`} fill={lab[1]} stroke={lab[2]} strokeWidth={2}/>
  <path d={`M-60 ${cy}Q0 ${lc} 60 ${cy}Q0 ${lc+28} -60 ${cy}Z`} fill={lab[0]} stroke={lab[2]} strokeWidth={2}/>
  <Brillo2 x={-14} y={lc+16} rx={22} ry={4} r={0} o={.55}/>
  {chispa>0&&<g transform={`translate(120 18) rotate(${s*40}) scale(${chispa*.5})`}><circle r={40} fill='#fff' opacity={.5} filter='url(#b6)'/><path d='M0 -44Q4 -6 44 0Q4 6 0 44Q-4 6 -44 0Q-4 -6 0 -44Z' fill='#fff'/></g>}
  {chispa>0&&<Brillo2 x={20} y={apU+10} rx={10} ry={3} r={-20} o={.9*chispa}/>}
  {sweat>0&&<g opacity={sweat} transform={`translate(-130 ${-120+sweat*60})`}><path d='M0 -30C14 -4 22 6 22 18A22 22 0 0 1 -22 18C-22 6 -14 -4 0 -30Z' fill='#bfe8ff' stroke='#4a90c8' strokeWidth={3}/><ellipse cx={-7} cy={12} rx={5} ry={9} fill='#fff' opacity={.8}/></g>}
 </g>;
};
// ---------- MANOS (palma, 4 dedos y pulgar unido a la palma, nudillos y uñas) ----------
const Mano:React.FC<{id:string;c?:C3;ext?:number[];th?:number;sp?:number;manga?:C3;reloj?:boolean}>=({id,c=PIEL_A,ext=[1,1,1,1],th=-50,sp=.7,manga,reloj=false})=>{
 const fx=[-40,-14,14,40],fl=[62,76,82,66],fw=[25,27,27,23];
 const palm='M-54 14C-62 -6 -58 -26 -52 -40L52 -40C58 -26 62 -6 54 14C50 66 42 100 32 122L-32 122C-42 100 -50 66 -54 14Z';
 const ta=th*RAD,tx=-44+Math.sin(ta)*88,ty=62-Math.cos(ta)*88;
 return <g>
  <VolS id={id+'th'} d={caps(-44,62,tx,ty,34)} c={c} o={4}/>
  <ellipse cx={tx-Math.sin(ta)*6} cy={ty+Math.cos(ta)*8} rx={9} ry={12} transform={`rotate(${th} ${tx} ${ty})`} fill='#ffeee6' opacity={.85}/>
  {fx.map((x,j)=>{const e=ext[j],Ln=fl[j]*(.35+.65*e),ang=(j-1.5)*sp*8*RAD,tpx=x+Math.sin(ang)*Ln,tpy=-30-Math.cos(ang)*Ln;
   return <g key={j}><VolS id={id+'f'+j} d={caps(x,-14,tpx,tpy,fw[j])} c={c} o={4}/>
    {e>.5&&<ellipse cx={tpx-Math.sin(ang)*4} cy={tpy+Math.cos(ang)*9} rx={8.5} ry={11} transform={`rotate(${ang/RAD} ${tpx} ${tpy})`} fill='#ffeee6' opacity={.85}/>}</g>;})}
  <VolS id={id+'pm'} d={palm} c={c} o={6}/>
  <ellipse cx={-30} cy={52} rx={26} ry={40} fill={c[0]} opacity={.35} filter='url(#b6)'/>
  {fx.map((x,j)=><path key={j} d={`M${x-10} -30Q${x} -40 ${x+10} -30`} stroke={c[2]} strokeWidth={3} fill='none' opacity={.55}/>)}
  {[0,1].map(j=><path key={j} d={`M-30 ${30+j*22}Q0 ${40+j*22} 36 ${28+j*22}`} stroke={c[2]} strokeWidth={3} fill='none' opacity={.4}/>)}
  {manga&&<><Vol id={id+'mg'} d='M-64 112L64 112L92 420L-92 420Z' c={manga} sw={50} o={14}/><Vol id={id+'pu'} d='M-62 108L62 108L66 142L-66 142Z' c={BLANCO} sw={20} o={6}/></>}
  {reloj&&<><Vol id={id+'rl'} d={caps(-52,126,52,126,26)} c={ORO} sw={14} o={4}/><circle cx={0} cy={126} r={22} fill='#fff' stroke='#a86a00' strokeWidth={5}/><path d='M0 126V112M0 126L10 130' stroke='#222' strokeWidth={3} strokeLinecap='round'/></>}
 </g>;
};
// Puño (o pulgar arriba): bloque con nudillos, cuatro dedos doblados y pulgar.
const Puno:React.FC<{id:string;c?:C3;up?:boolean;manga?:C3}>=({id,c=PIEL_T,up=false,manga=GRIS})=>up?<g>
